// Lightweight SVG charts. All inputs are numbers generated by the app (no user HTML).
import { h } from './ui.js';

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/** Progress ring. kind: 'min' (more is better), 'max' (stay under). */
export function ring(value, target, { size = 86, stroke = 9, label = '', sub = '', kind = 'min' } = {}) {
  const pct = target ? value / target : 0;
  const r = (size - stroke) / 2; const c = 2 * Math.PI * r;
  const shown = Math.min(pct, 1);
  const cls = kind === 'max' ? (pct <= 1 ? 'good' : pct <= 1.15 ? 'near' : 'bad') : (pct >= 1 ? 'good' : pct >= 0.75 ? 'near' : 'low');
  const svg = `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" role="img" aria-label="${esc(label)} ${Math.round(pct * 100)}%">
    <circle cx="${size / 2}" cy="${size / 2}" r="${r}" class="ring-bg" stroke-width="${stroke}" fill="none"/>
    ${shown > 0.005 ? `<circle cx="${size / 2}" cy="${size / 2}" r="${r}" class="ring-fg ${cls}" stroke-width="${stroke}" fill="none"
      stroke-dasharray="${c * shown} ${c}" stroke-linecap="round" transform="rotate(-90 ${size / 2} ${size / 2})"/>` : ''}
    <text x="50%" y="48%" text-anchor="middle" class="ring-val">${Math.round(pct * 100)}%</text>
    <text x="50%" y="66%" text-anchor="middle" class="ring-sub">${esc(sub)}</text></svg>`;
  return h('div', { class: 'ring', html: svg });
}

/** Horizontal bar against a target marker. */
export function targetBar(value, target, { kind = 'min', max } = {}) {
  const top = max || Math.max(target * 1.5, value * 1.05, 1);
  const w = Math.min(100, (value / top) * 100);
  const tm = Math.min(100, (target / top) * 100);
  const pct = target ? value / target : 0;
  const cls = kind === 'max' ? (pct <= 1 ? 'good' : pct <= 1.15 ? 'near' : 'bad') : (pct >= 1 ? 'good' : pct >= 0.75 ? 'near' : 'low');
  return h('div', { class: 'tbar', role: 'img', 'aria-label': `${Math.round(pct * 100)}%` },
    h('div', { class: `tbar-fill ${cls}`, style: { width: `${w}%` } }),
    h('div', { class: 'tbar-mark', style: { insetInlineStart: `${tm}%` } }));
}

/** Line chart with optional target line. points: [{x: label, y: number|null}] */
export function lineChart(points, { target = null, height = 150, unit = '', color = 'var(--c1)', yMax } = {}) {
  const W = 340; const H = height; const pad = { l: 34, r: 8, t: 10, b: 22 };
  const ys = points.map((p) => p.y).filter((y) => y != null);
  const maxY = yMax || Math.max(1, ...(ys.length ? ys : [0]), target || 0) * 1.12;
  const x = (i) => pad.l + (i * (W - pad.l - pad.r)) / Math.max(1, points.length - 1);
  const y = (v) => pad.t + (H - pad.t - pad.b) * (1 - v / maxY);
  let path = ''; let started = false;
  points.forEach((p, i) => { if (p.y == null) { started = false; return; } path += `${started ? 'L' : 'M'}${x(i).toFixed(1)},${y(p.y).toFixed(1)} `; started = true; });
  const dots = points.map((p, i) => (p.y == null ? '' : `<circle cx="${x(i)}" cy="${y(p.y)}" r="2.6" fill="${color}"/>`)).join('');
  const grid = [0, 0.5, 1].map((f) => { const v = maxY * f; return `<line x1="${pad.l}" x2="${W - pad.r}" y1="${y(v)}" y2="${y(v)}" class="grid"/><text x="${pad.l - 4}" y="${y(v) + 3}" text-anchor="end" class="axis">${Math.round(v)}</text>`; }).join('');
  const tl = target ? `<line x1="${pad.l}" x2="${W - pad.r}" y1="${y(target)}" y2="${y(target)}" class="target-line"/>` : '';
  const step = Math.ceil(points.length / 6);
  const labels = points.map((p, i) => (i % step === 0 || i === points.length - 1 ? `<text x="${x(i)}" y="${H - 6}" text-anchor="middle" class="axis">${esc(p.x)}</text>` : '')).join('');
  const svg = `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="trend ${esc(unit)}">${grid}${tl}<path d="${path}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>${dots}${labels}</svg>`;
  return h('div', { class: 'chart', dir: 'ltr', html: svg });
}

/** Vertical bars. bars: [{label, value, cls?}] */
export function barChart(bars, { target = null, height = 140 } = {}) {
  const W = 340; const H = height; const pad = { l: 30, r: 6, t: 8, b: 22 };
  const maxY = Math.max(1, ...bars.map((b) => b.value || 0), target || 0) * 1.12;
  const bw = (W - pad.l - pad.r) / Math.max(1, bars.length);
  const y = (v) => pad.t + (H - pad.t - pad.b) * (1 - v / maxY);
  const rects = bars.map((b, i) => {
    const v = b.value || 0;
    return `<rect x="${pad.l + i * bw + bw * 0.18}" y="${y(v)}" width="${bw * 0.64}" height="${Math.max(0, H - pad.b - y(v))}" rx="4" class="bar ${b.cls || ''}"/>` +
      `<text x="${pad.l + i * bw + bw / 2}" y="${H - 6}" text-anchor="middle" class="axis">${esc(b.label)}</text>`;
  }).join('');
  const tl = target ? `<line x1="${pad.l}" x2="${W - pad.r}" y1="${y(target)}" y2="${y(target)}" class="target-line"/><text x="${pad.l - 4}" y="${y(target) + 3}" text-anchor="end" class="axis">${Math.round(target)}</text>` : '';
  return h('div', { class: 'chart', dir: 'ltr', html: `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img">${rects}${tl}</svg>` });
}

/** Stacked 100% bar, e.g. NOVA energy share. parts: [{value, cls, label}] */
export function stackBar(parts) {
  const total = parts.reduce((a, p) => a + (p.value || 0), 0) || 1;
  return h('div', { class: 'stack', dir: 'ltr' }, parts.map((p) => h('div', { class: `stack-part ${p.cls}`, style: { width: `${(100 * (p.value || 0)) / total}%` }, title: `${p.label}: ${Math.round((100 * (p.value || 0)) / total)}%` })));
}

/** Macro donut. parts: [{value, cls}] */
export function donut(parts, { size = 96, stroke = 14, center = '' } = {}) {
  const total = parts.reduce((a, p) => a + p.value, 0) || 1;
  const r = (size - stroke) / 2; const c = 2 * Math.PI * r;
  let off = 0;
  const segs = parts.map((p) => { const len = (p.value / total) * c; const s = `<circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke-width="${stroke}" class="${p.cls}" stroke-dasharray="${len} ${c - len}" stroke-dashoffset="${-off}" transform="rotate(-90 ${size / 2} ${size / 2})"/>`; off += len; return s; }).join('');
  return h('div', { class: 'donut', html: `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">${segs}<text x="50%" y="54%" text-anchor="middle" class="ring-val">${esc(center)}</text></svg>` });
}

/** Meal-quality dial: 0–100 with band colour. */
export function scoreDial(score, { size = 112 } = {}) {
  const stroke = 11; const r = (size - stroke) / 2; const c = 2 * Math.PI * r;
  const v = score == null ? 0 : Math.max(0, Math.min(100, score));
  const cls = score == null ? 'na' : score >= 75 ? 'excellent' : score >= 60 ? 'good' : score >= 45 ? 'fair' : 'poor';
  const svg = `<svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" role="img" aria-label="Meal score ${score ?? 'not scored'} of 100">
    <circle cx="${size / 2}" cy="${size / 2}" r="${r}" class="ring-bg" stroke-width="${stroke}" fill="none"/>
    ${v > 0 ? `<circle cx="${size / 2}" cy="${size / 2}" r="${r}" class="dial-fg dial-${cls}" stroke-width="${stroke}" fill="none" stroke-dasharray="${(c * v) / 100} ${c}" stroke-linecap="round" transform="rotate(-90 ${size / 2} ${size / 2})"/>` : ''}
    <text x="50%" y="52%" text-anchor="middle" class="dial-val">${score ?? '—'}</text>
    <text x="50%" y="68%" text-anchor="middle" class="ring-sub">/ 100</text></svg>`;
  return h('div', { class: 'dial', html: svg });
}
